static int atl2_probe(struct pci_dev *pdev, const struct pci_device_id *ent) /* <=== atl2_probe */ 
{
	struct net_device *netdev;
	struct atl2_adapter *adapter;
	static int cards_found;
	unsigned long mmio_start;
	int mmio_len;
	int err;

	cards_found = 0;

	err = pci_enable_device(pdev);
	if (err)
		return err;

